"use strict";const tabButtons=document.querySelectorAll(".tab-btn"),tabPanels=document.querySelectorAll(".tab-panel");function activateTab(t){tabButtons.forEach(e=>{const a=e.dataset.tab===t;e.classList.toggle("active",a),e.setAttribute("aria-pressed",a?"true":"false")}),tabPanels.forEach(e=>{e.hidden=e.dataset.panel!==t})}tabButtons.forEach(t=>{t.addEventListener("click",()=>{activateTab(t.dataset.tab)})}),function(){const t=document.getElementById("mentors-body");if(!t)return;t.innerHTML=[{rang:1,nom:"Yassine El Amrani",filiere:"DEV",aides:24,note:4.9,badges:5},{rang:2,nom:"Lea Bernard",filiere:"FRONT",aides:18,note:4.8,badges:4},{rang:3,nom:"Sofia Martin",filiere:"DATA",aides:15,note:4.7,badges:4}].map(t=>`\n    <tr>\n      <td>${t.rang}</td>\n      <td>${t.nom}</td>\n      <td>${t.filiere}</td>\n      <td>${t.aides}</td>\n      <td>${t.note}</td>\n      <td>${t.badges}</td>\n    </tr>\n  `).join("")}();